export fn minimum_tickets_cost(v:[*c]const i64,n:usize)i64{if(v==null or n<4 or n>369 or v[0]<0 or v[0]>365)return -1;const d:usize=@intCast(v[0]);if(n!=d+4)return -1;var travel=[_]bool{false}**366;for(0..d)|i|{const x=v[i+1];if(x<1 or x>365 or travel[@intCast(x)])return -1;travel[@intCast(x)]=true;}const c0=v[d+1];const c1=v[d+2];const c2=v[d+3];if(c0<0 or c0>1000000 or c1<0 or c1>1000000 or c2<0 or c2>1000000)return -1;var dp=[_]i64{0}**397;var day:usize=365;while(day>0){dp[day]=dp[day+1];if(travel[day]){dp[day]=@min(c0+dp[day+1],@min(c1+dp[day+7],c2+dp[day+30]));}day-=1;}return dp[1];}
